function useIconComponent(MuiComp, LucideComp) {
  // 第三参 getServerSnapshot：getIconStyleSnapshot 只读模块级字符串快照、不触
  // DOM，服务端渲染与 hydration 取到同一值，避免缺省 server snapshot 在 SSR 下
  // 抛错或首帧闪烁。
  const iconStyle = useSyncExternalStore(
    subscribeIconStyle,
    getIconStyleSnapshot,
    getIconStyleSnapshot,
  );
  return iconStyle === "mui" ? MuiComp : LucideComp;
}

// 分发器统一生成入口：MUI 经静态 muiName 识别 SvgIcon（InputAdornment 等
// 装饰位按此判定是否为图标），forwardRef 包装会丢失该标识，此处补回。
// PURE 注解保留在各导出点，tree-shaking 语义不变。
function createStyleDispatcherIcon(MuiComp, LucideComp) {
  const DispatcherIcon = /*#__PURE__*/ React.forwardRef(function StyleDispatcherIcon(props, ref) {
    const Icon = useIconComponent(MuiComp, LucideComp);
    return <Icon {...props} ref={ref} />;
  });
  DispatcherIcon.muiName = "SvgIcon";
  return DispatcherIcon;
}

